sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.cah-footer {
  width: 100%;
  background: #111827;
  color: #ffffff;
  font-family: Arial, sans-serif;
}

.footer-container {
  max-width: 1200px;
  margin: auto;
  padding: 70px 30px 50px;

  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 50px;
}

.footer-logo {
  display: flex;
  align-items: center;
  margin-bottom: 20px;
}

.footer-logo-icon {
  width: 42px;
  height: 42px;

  display: flex;
  align-items: center;
  justify-content: center;

  background: #53BA00;
  color: white;

  border-radius: 10px;

  font-size: 20px;
  font-weight: bold;

  margin-right: 10px;
}

.footer-brand-name {
  font-size: 16px;
  font-weight: bold;
  letter-spacing: 1px;
}

.footer-brand-subtitle {
  color: #9ca3af;
  font-size: 13px;
  margin-top: 2px;
}

.footer-brand p {
  max-width: 350px;
  color: #9ca3af;
  font-size: 14px;
  line-height: 1.7;
}

.powered-by {
  display: inline-block;
  margin-top: 10px;
  padding: 7px 12px;

  background: #1f2937;
  border-radius: 6px;

  color: #60a5fa;
  font-size: 12px;
}

.footer-column h4 {
  margin: 5px 0 20px;
  font-size: 15px;
  color: #ffffff;
}

.footer-column a {
  display: block;
  margin-bottom: 12px;

  color: #9ca3af;
  text-decoration: none;
  font-size: 14px;
}

.footer-column a:hover {
  color: #ffffff;
}

.footer-bottom {
  max-width: 1200px;
  margin: auto;

  padding: 20px 30px;

  border-top: 1px solid #374151;

  display: flex;
  justify-content: space-between;
  align-items: center;

  color: #B0B0B0;
  font-size: 12px;
}

.footer-bottom-links {
  display: flex;
  gap: 20px;
}

.footer-bottom a {
  color: #9ca3af;
  text-decoration: none;
}

@media (max-width: 900px) {

  .footer-container {
    grid-template-columns: repeat(2, 1fr);
  }

}

@media (max-width: 600px) {

  .footer-container {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 15px;
    text-align: center;
  }

}
